cd /tmp && cat > v.c <<'EOF'
typedef struct { float x, y, z; } Vec3;
Vec3 vector_create(float x, float y, float z) { Vec3 v = {x,y,z}; return v; }
Vec3 vector_add(Vec3 a, Vec3 b) { return vector_create(a.x+b.x, a.y+b.y, a.z+b.z); }
EOF
gcc -O0 -c v.c -o v.o && objdump -d -M intel v.o | sed -n '/<vector_add>:/,/^$/p'

